import{_ as l,a0 as d,w as o,s as g,I as a,x as n,a1 as t,A as e,ao as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"在 Linux 中如何使用 gdb 调试 C 程序 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 中如何使用 gdb 调试 C 程序 | LCTT (201702) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 中如何使用 gdb 调试 C 程序 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 中如何使用 gdb 调试 C 程序 | LCTT (201702) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201702/20170116 How to debug C programs in Linux using gdb","title":"在 Linux 中如何使用 gdb 调试 C 程序","tag":"201702","desc":""},"relativePath":"201702/20170116 How to debug C programs in Linux using gdb.md","filePath":"[post].md"}'),r={name:"201702/20170116 How to debug C programs in Linux using gdb.md"};function h(b,s,u,c,k,f){const i=d("Link");return o(),g("div",null,[s[24]||(s[24]=a("h1",{id:"在-linux-中如何使用-gdb-调试-c-程序",tabindex:"-1"},[n("在 Linux 中如何使用 gdb 调试 C 程序 "),a("a",{class:"header-anchor",href:"#在-linux-中如何使用-gdb-调试-c-程序","aria-label":"Permalink to “在 Linux 中如何使用 gdb 调试 C 程序”"},"​")],-1)),s[25]||(s[25]=a("p",null,"无论多么有经验的程序员，开发的任何软件都不可能完全没有 bug。因此，排查及修复 bug 成为软件开发周期中最重要的任务之一。有许多办法可以排查 bug（测试、代码自审等等），但是还有一些专用软件（称为调试器）可以帮助准确定位问题的所在，以便进行修复。",-1)),a("p",null,[s[1]||(s[1]=n("如果你是 C/C++ 程序员，或者使用 Fortran 和 Modula-2 编程语言开发软件，那么你将会很乐意知道有这么一款优秀的调试器 - ",-1)),t(i,{href:"https://www.sourceware.org/gdb/"},{default:e(()=>[...s[0]||(s[0]=[n("GDB",-1)])]),_:1}),s[2]||(s[2]=n(" - 可以帮你更轻松地调试代码 bug 以及其它问题。在这篇文章中，我们将讨论一下 GDB 调试器的基础知识，包括它提供的一些有用的功能/选项。",-1))]),s[26]||(s[26]=a("p",null,"在我们开始之前，值得一提的是，文章中的所有说明和示例都已经在 Ubuntu 14.04 LTS 中测试过。教程中的示例代码都是 C 语言写的；使用的 shell 为 bash（4.3.11）；GDB 版本为 7.7.1。",-1)),s[27]||(s[27]=a("h3",{id:"gdb-调试器基础",tabindex:"-1"},[n("GDB 调试器基础 "),a("a",{class:"header-anchor",href:"#gdb-调试器基础","aria-label":"Permalink to “GDB 调试器基础”"},"​")],-1)),s[28]||(s[28]=a("p",null,"通俗的讲，GDB 可以让你看到程序在执行过程时的内部流程，并帮你明确问题的所在。我们将在下一节通过一个有效的示例来讨论 GDB 调试器的用法，但在此之前，我们先来探讨一些之后对你有帮助的基本要点。",-1)),s[29]||(s[29]=a("p",null,[n("首先，为了能够顺利使用类似 GDB 这样的调试器，你必须以指定的方式编译程序，让编译器产生调试器所需的调试信息。例如，在使用 gcc 编译器（我们将在本教程之后的章节用它来编译 C 程序示例）编译代码的时候，你需要使用 "),a("code",null,"-g"),n(" 命令行选项。")],-1)),a("p",null,[s[4]||(s[4]=n("想要了解 gcc 编译器手册页中关于 ",-1)),s[5]||(s[5]=a("code",null,"-g",-1)),s[6]||(s[6]=n(" 命令行选项相关的内容，请看",-1)),t(i,{href:"https://linux.die.net/man/1/gcc"},{default:e(()=>[...s[3]||(s[3]=[n("这里",-1)])]),_:1}),s[7]||(s[7]=n("。",-1))]),s[30]||(s[30]=p('<p>下一步，确保在你的系统中已经安装 GDB 调试器。如果没有安装，而且你使用的是基于 Debian 的系统（如 Ubuntu），那么你就可以使用以下命令轻松安装该工具：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install gdb</span></span></code></pre></div>',2)),a("p",null,[s[9]||(s[9]=n("在其他发行版上的安装方法，请看",-1)),t(i,{href:"https://www.sourceware.org/gdb/download/"},{default:e(()=>[...s[8]||(s[8]=[n("这里",-1)])]),_:1}),s[10]||(s[10]=n("。",-1))]),s[31]||(s[31]=p(`<p>现在，当你按照上述的方式编译完程序（<code>gcc -g</code> 命令行选项），同时也已经安装好 GDB 调试器，那么你就可以使用以下命令让程序在调试模式中运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>gdb [可执行程序的名称]</span></span></code></pre></div><p>这样做会初始化 GDB 调试器，但你的可执行程序此时还不会被启动。在这个时候你就可以定义调试相关的设置。例如，你可以在特定行或函数中设置一个断点让 GDB 在该行暂停程序的执行。</p><p>接着，为了启动你的程序，你必须输入执行以下 gdb 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>run</span></span></code></pre></div><p>在这里，值得一提的是，如果你的程序需要一些命令行参数，那么你可以在这里指定这些参数。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>run [arguments]</span></span></code></pre></div><p>GDB 提供了很多有用的命令，在调试的时候总是能派的上用场。我们将在下一节讨论其中一部分命令。</p><h3 id="gdb-调试器用例" tabindex="-1">GDB 调试器用例 <a class="header-anchor" href="#gdb-调试器用例" aria-label="Permalink to “GDB 调试器用例”">​</a></h3><p>现在我们对 GDB 及其用法有了基本的概念。因此，让我们举例来应用所学的知识。这是一段示例代码：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>int main()</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    int out = 0, tot = 0, cnt = 0;</span></span>
<span class="line"><span>    int val[] = {5, 54, 76, 91, 35, 27, 45, 15, 99, 0};</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    while(cnt &lt; 10)</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        out = val[cnt];</span></span>
<span class="line"><span>        tot = tot + 0xffffffff/out;</span></span>
<span class="line"><span>        cnt++;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    printf(&quot;\\n Total = [%d]\\n&quot;, tot);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>简单说明一下这段代码要做什么事。获取 <code>val</code> 数组中每一个值，将其赋值给 <code>out</code> 变量，然后将 <code>tot</code> 之前的值与 <code>0xffffffff/out</code> 的结果值累加，赋值给 <code>tot</code> 变量。</p><p>这里遇到的问题是，当执行这段代码编译后的可执行程序时，产生以下错误：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ./gdb-test </span></span>
<span class="line"><span>Floating point exception (core dumped)</span></span></code></pre></div><p>因此，要调试这段代码，第一步是使用 <code>-g</code> 选项编译程序。命令如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>gcc -g -Wall gdb-test.c -o gdb-test</span></span></code></pre></div><p>接着，让我们运行 GDB 调试器并指定要调试的可执行程序。命令如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>gdb ./gdb-test</span></span></code></pre></div><p>现在，我刚才得到的错误是 <code>Floating point exception</code>，大部分人可能已经知道，这是因为 <code>n % x</code>，当 x 为 0 时导致的错误。所以，考虑到这一点，我在 11 行代码除法运算的位置处添加了一个断点。如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(gdb) break 11</span></span></code></pre></div><p>注意 <code>(gdb)</code> 是调试器的提示信息，我只输入了 <code>break 11</code> 命令。</p><p>现在，让 GDB 开始运行程序：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>run</span></span></code></pre></div><p>当断点第一次被命中时，GDB 显示如下输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Breakpoint 1, main () at gdb-test.c:11</span></span>
<span class="line"><span>11 tot = tot + 0xffffffff/out;</span></span>
<span class="line"><span>(gdb)</span></span></code></pre></div><p>正如你所看到的那样，调试器会显示断点所在的行代码。现在，让我们打印出此时 <code>out</code> 的值。如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(gdb) print out</span></span>
<span class="line"><span>$1 = 5</span></span>
<span class="line"><span>(gdb)</span></span></code></pre></div><p>如上所示，值 <code>5</code> 被打印出来了。这个时候一切都还是正常的。让调试器继续执行程序直到命中下一个断点，可以通过使用 <code>c</code> 命令来完成：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>c</span></span></code></pre></div><p>重复上述操作，直到 <code>out</code> 值变为 <code>0</code> 时。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>...</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>Breakpoint 1, main () at gdb-test.c:11</span></span>
<span class="line"><span>11 tot = tot + 0xffffffff/out;</span></span>
<span class="line"><span>(gdb) print out</span></span>
<span class="line"><span>$2 = 99</span></span>
<span class="line"><span>(gdb) c</span></span>
<span class="line"><span>Continuing.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Breakpoint 1, main () at gdb-test.c:11</span></span>
<span class="line"><span>11 tot = tot + 0xffffffff/out;</span></span>
<span class="line"><span>(gdb) print out</span></span>
<span class="line"><span>$3 = 0</span></span>
<span class="line"><span>(gdb)</span></span></code></pre></div><p>现在，为了进一步确认问题，我使用 GDB 的 <code>s</code>（或 <code>step</code>） 命令代替 <code>c</code> 命令。因为，我只想让当前程序在第 11 行之后暂停，再一步步执行，看看这个时候是否会发生崩溃。</p><p>以下是执行之后输出信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(gdb) s</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Program received signal SIGFPE, Arithmetic exception.</span></span>
<span class="line"><span>0x080484aa in main () at gdb-test.c:11</span></span>
<span class="line"><span>11 tot = tot + 0xffffffff/out;</span></span></code></pre></div><p>是的，如上输出的第一行内容所示，这就是抛出异常的地方。当我再次尝试运行 <code>s</code> 命令时，问题最终也得到了确认：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(gdb) s</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Program terminated with signal SIGFPE, Arithmetic exception.</span></span>
<span class="line"><span>The program no longer exists.</span></span></code></pre></div><p>通过这种方式，你就可以使用 GDB 调试你的程序。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>GDB 提供了很多功能供用户研究和使用，在这里，我们仅仅只介绍了很少一部分内容。通过 GDB 的手册页可以进一步了解这个工具，当你在调试代码的时候，尝试使用一下它。GDB 调试器有一定的学习难度，但是它很值得你下功夫学习。</p><hr>`,40)),a("p",null,[s[12]||(s[12]=n("via: ",-1)),t(i,{href:"https://www.howtoforge.com/tutorial/how-to-debug-c-programs-in-linux-using-gdb/"},{default:e(()=>[...s[11]||(s[11]=[n("https://www.howtoforge.com/tutorial/how-to-debug-c-programs-in-linux-using-gdb/",-1)])]),_:1})]),a("p",null,[s[16]||(s[16]=n("作者：",-1)),t(i,{href:"https://www.howtoforge.com/tutorial/how-to-debug-c-programs-in-linux-using-gdb/"},{default:e(()=>[...s[13]||(s[13]=[n("Ansh",-1)])]),_:1}),s[17]||(s[17]=n(" 译者：",-1)),t(i,{href:"https://github.com/zhb127"},{default:e(()=>[...s[14]||(s[14]=[n("zhb127",-1)])]),_:1}),s[18]||(s[18]=n(" 校对：",-1)),t(i,{href:"https://github.com/jasminepeng"},{default:e(()=>[...s[15]||(s[15]=[n("jasminepeng",-1)])]),_:1})]),a("p",null,[s[21]||(s[21]=n("本文由 ",-1)),t(i,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[19]||(s[19]=[n("LCTT",-1)])]),_:1}),s[22]||(s[22]=n(" 原创编译，",-1)),t(i,{href:"https://linux.cn/"},{default:e(()=>[...s[20]||(s[20]=[n("Linux中国",-1)])]),_:1}),s[23]||(s[23]=n(" 荣誉推出",-1))])])}const y=l(r,[["render",h]]);export{x as __pageData,y as default};
